import java.util.Scanner;

class GCD {

    public static void main(String[] args) {

        Scanner scan = new Scanner(System.in);

        int m = scan.nextInt();
        int n = scan.nextInt();

        while (n != 0) {

            int remainder = m % n;

            m = n;
            n = remainder;
        }

        int gcd = m;

        System.out.println(gcd);
    }
}

